export CARGO_BUILD_JOBS=2 CARGO_PROFILE_DEV_DEBUG=0; bash tests/guests/processes/build.sh /tmp/gb > /tmp/gb.log 2>&1; echo guests=$?; tail -3 /tmp/gb.log; cargo build --locked -p paludarium 2>&1 | grep -v warning | tail -1; F="-static -O1 -fno-stack-protector -fcf-protection=none -fno-pie -no-pie"; for c in veth-igmp-neighbours net-dev-counters; do musl-gcc $F -o /tmp/$c tests/guests/processes/$c.c; echo "== $c"; ./target/debug/paludarium /tmp/$c $c 2>&1; echo "== end $c"; done; echo build=0
